class Node:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None

def insert(root, val):
    if root is None:
        return Node(val)
    if val < root.val:
        root.left = insert(root.left, val)
    else:
        root.right = insert(root.right, val)
    return root

def sorted_list_to_bst_brute(vals):
    root = None
    for v in vals:
        root = insert(root, v)          # inserting sorted values one by one
    return root

