class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def sorted_list_to_bst(head):
    vals = []
    node = head
    while node:
        vals.append(node.val)
        node = node.next

    def build(l, r):
        if l > r:
            return None
        mid = (l + r) // 2                   # pick the middle as root
        root = TreeNode(vals[mid])
        root.left = build(l, mid - 1)          # left half becomes left subtree
        root.right = build(mid + 1, r)         # right half becomes right subtree
        return root

    return build(0, len(vals) - 1)

