#include <bits/stdc++.h>
using namespace std;

struct TreeNode { int val; TreeNode* left; TreeNode* right; TreeNode(int v): val(v), left(nullptr), right(nullptr) {} };

vector<int> vals;

TreeNode* build(int l, int r) {
    if (l > r) return nullptr;
    int mid = (l + r) / 2;                          // pick the middle as root
    TreeNode* root = new TreeNode(vals[mid]);
    root->left = build(l, mid - 1);                   // left half becomes left subtree
    root->right = build(mid + 1, r);                  // right half becomes right subtree
    return root;
}

TreeNode* sortedListToBST(ListNode* head) {
    vals.clear();
    while (head) { vals.push_back(head->val); head = head->next; }
    return build(0, (int)vals.size() - 1);
}
